def _extract_pixel_grid_from_lines(lines, width):
    """Reconstruct the true (height=2*len(lines), width=width) RGB pixel grid from
    half-block-encoded ANSI lines.

    Each terminal character cell packs two vertical "pixels" via a half-block glyph:
    '▀' (upper half block) shows fg on top / bg on bottom; '▄' (lower half block) is the
    reverse. Plain (uncolored) cells — e.g. blank margins — become None ("no pixel here")
    in both rows.
    """
    grid = []
    for line in lines:
        top_row = [None] * width
        bottom_row = [None] * width
        col = 0
        cur_fg = None
        cur_bg = None
        for m in _TOKEN_RE.finditer(line):
            esc, text = m.group(1), m.group(2)
            if esc:
                code = esc[2:-1]
                parts = code.split(';')
                if parts[0] in ('0', ''):
                    cur_fg = cur_bg = None
                elif len(parts) == 5 and parts[1] == '2':
                    rgb = (int(parts[2]), int(parts[3]), int(parts[4]))
                    if parts[0] == '38':
                        cur_fg = rgb
                    elif parts[0] == '48':
                        cur_bg = rgb
                continue
            for ch in text:
                if col >= width:
                    break
                if ch == '▀':
                    top_row[col], bottom_row[col] = cur_fg, cur_bg
                elif ch == '▄':
                    top_row[col], bottom_row[col] = cur_bg, cur_fg
                col += 1
        grid.append(top_row)
        grid.append(bottom_row)
    return grid


def _extract_full_pixel_grid():
    """Reconstruct the true (height=2*_LOGO_ROWS, width=_LOGO_W) RGB pixel grid from the
    half-block-encoded _LOGO_LINES (the full-size logo used elsewhere, e.g. dendros config)."""
    return _extract_pixel_grid_from_lines(_LOGO_LINES, _LOGO_W)


_FULL_PIXEL_GRID = _extract_full_pixel_grid()  # (2*_LOGO_ROWS) x _LOGO_W RGB-or-None

# Higher-fidelity source for build_small_logo() below — downsampling from the 84x84
# dendros_small.png-derived art gives a far more recognizable small icon than shrinking
# the already-low-res 42x21 _LOGO_LINES (which was hand-tuned for its own size, not as a
# source for further shrinking).
_HQ_PIXEL_GRID = _extract_pixel_grid_from_lines(_HQ_LOGO_LINES, _HQ_LOGO_W)


def _downsample_pixel_grid(grid, target_h, target_w):
    """Block-average `grid` down to target_h x target_w. None cells don't contribute;
    a target cell with no non-None source pixels stays None (transparent)."""
    src_h = len(grid)
    src_w = len(grid[0]) if grid else 0
    out = []
    for ty in range(target_h):
        y0 = ty * src_h // target_h
        y1 = max(y0 + 1, (ty + 1) * src_h // target_h)
        row_out = []
        for tx in range(target_w):
            x0 = tx * src_w // target_w
            x1 = max(x0 + 1, (tx + 1) * src_w // target_w)
            samples = [grid[y][x] for y in range(y0, y1) for x in range(x0, x1)
                       if grid[y][x] is not None]
            if not samples:
                row_out.append(None)
            else:
                n = len(samples)
                row_out.append((
                    sum(s[0] for s in samples) // n,
                    sum(s[1] for s in samples) // n,
                    sum(s[2] for s in samples) // n,
                ))
        out.append(row_out)
    return out


def _encode_pixel_pair(top, bottom):
    """Render one terminal cell from its (top, bottom) pixel pair as a half-block glyph."""
    if top is None and bottom is None:
        return ' '
    if top is not None and bottom is not None:
        return f'\x1b[38;2;{top[0]};{top[1]};{top[2]}m\x1b[48;2;{bottom[0]};{bottom[1]};{bottom[2]}m▀\x1b[0m'
    if top is not None:
        return f'\x1b[38;2;{top[0]};{top[1]};{top[2]}m▀\x1b[0m'
    return f'\x1b[38;2;{bottom[0]};{bottom[1]};{bottom[2]}m▄\x1b[0m'


def build_small_logo(target_rows=4, target_cols=None):
    """Return a small downsampled version of the logo as `target_rows` ANSI-encoded strings.

    Real block-averaging of the high-fidelity 84x84 source (_HQ_PIXEL_GRID, from
    dendros_small.png — see _HQ_LOGO_LINES above), not a crop and not a re-shrink of the
    already-low-res 42x21 _LOGO_LINES — for contexts too small for the full logo (e.g. the
    launch TUI's header). `target_cols` defaults to `target_rows*2` (the source is square
    in true-pixel terms — 84x84 — so doubling rows back to pixel-row units keeps the
    on-screen aspect correct).
    """
    target_rows = max(1, target_rows)
    if target_cols is None:
        target_cols = target_rows * 2
    target_h = target_rows * 2
    small = _downsample_pixel_grid(_HQ_PIXEL_GRID, target_h, target_cols)
    lines = []
    for r in range(0, target_h, 2):
        top = small[r]
        bottom = small[r + 1] if r + 1 < target_h else [None] * target_cols
        lines.append(''.join(_encode_pixel_pair(top[c], bottom[c]) for c in range(target_cols)))
    return lines


def _shift_rgb(rgb, delta_hue):
    """Return rgb with hue rotated by delta_hue (0–1).  Near-grey pixels are unchanged."""
    if rgb is None:
        return None
    r, g, b = rgb[0] / 255.0, rgb[1] / 255.0, rgb[2] / 255.0
    h, s, v = colorsys.rgb_to_hsv(r, g, b)
    if s < _SAT_THRESHOLD:
        return rgb
    h = (h + delta_hue) % 1.0
    r2, g2, b2 = colorsys.hsv_to_rgb(h, s, v)
    return (round(r2 * 255), round(g2 * 255), round(b2 * 255))


def _render_logo_line(segs, hue_offset):
    """Re-encode one parsed logo line with the given hue shift applied."""
    parts = []
    for text, fg, bg in segs:
        sfg = _shift_rgb(fg, hue_offset)
        sbg = _shift_rgb(bg, hue_offset)
        if sfg is not None:
            parts.append(f'\x1b[38;2;{sfg[0]};{sfg[1]};{sfg[2]}m')
        if sbg is not None:
            parts.append(f'\x1b[48;2;{sbg[0]};{sbg[1]};{sbg[2]}m')
        parts.append(text)
        if sfg is not None or sbg is not None:
            parts.append('\x1b[0m')
    return ''.join(parts)


def _make_title_line(hue_offset):
    """Build the colored DendROS title string with hue-shifted colors."""
    b = _shift_rgb(_TITLE_BLUE,   hue_offset)
    o = _shift_rgb(_TITLE_ORANGE, hue_offset)
    return (
        ' ' * _TITLE_PAD
        + f'\x1b[1m\x1b[38;2;{b[0]};{b[1]};{b[2]}mD e n d\x1b[0m'
        + '   '
        + f'\x1b[1m\x1b[38;2;{o[0]};{o[1]};{o[2]}mR O S\x1b[0m'
    )


def draw_logo_ansi(start_row, hue_offset=0.0):
    """Write the logo and DendROS title to stdout using raw 24-bit ANSI escape codes.

    Called after scr.refresh() each frame. Curses never writes to this region,
    so refresh() never clears it — the art persists without flicker.
    """
    out = []
    for i, segs in enumerate(_LOGO_PARSED):
        out.append(f'\033[{start_row + i + 1};1H{_render_logo_line(segs, hue_offset)}')
    title_row = start_row + _LOGO_ROWS - 1
    out.append(f'\033[{title_row};1H{_make_title_line(hue_offset)}')
    sys.stdout.write(''.join(out))
    sys.stdout.flush()
